            B.q("ai-m4-16", "ai-cosmos-sdk", "Each time a recipe is opened, its views counter must go up by one. The current code reads the whole item, adds one in Python and replaces the item, and concurrent opens lose counts. Which call fixes this in one operation?", listOf("upsert_item(body=item) after adding one to item[\"views\"] in Python", "query_items(query=\"SELECT VALUE c.views + 1 FROM c WHERE c.id = @id\")", "patch_item(item=id, partition_key=pk, patch_operations=[{\"op\": \"set\", \"path\": \"/views\", \"value\": views + 1}])", "patch_item(item=id, partition_key=pk, patch_operations=[{\"op\": \"incr\", \"path\": \"/views\", \"value\": 1}])"), setOf(3), "Partial document update (patch) changes only the listed paths on the server. The incr operation adds to a number atomically, so concurrent opens do not overwrite each other, and the item does not travel to the client and back.",
                scenario = "Tideline Recipes shows a views counter on every recipe in its Android app.",
